54	 /// — the canonical message-list view that providers consume.
55	 ///
56	 /// **Provider-translator caveat:** `Compacted` events render as
57	 /// [`Item::System`]. Both shipped provider translators (SMA-316 OpenAI,
58	 /// SMA-317 Anthropic) reshape system messages — Anthropic hoists every
59	 /// `Item::System` into the top-level `system` field; OpenAI concatenates
60	 /// multiple system blocks into one at the top of the conversation. The
61	 /// "summary replaces turns 1..N at this position" semantic is therefore
62	 /// observation-only in the event log; the model sees the summary text but
63	 /// as a top-level system instruction, not a positional cutover.
64	+///
65	+/// **Repair of old handoff logs.** A session that a core version before
66	+/// SMA-810 stored has the result of each handoff transfer call at the end of
67	+/// the run, after the events of the target agent. `project` moves each such
68	+/// result to directly after the transfer calls of its handoff response, in
69	+/// call order. If a moved result has the synthetic cancel text, `project`
70	+/// replaces it with `transferred to {target}` (the first transfer call of the
71	+/// response) or `transfer not performed: this response already transferred
72	+/// to {target}` (each other transfer call). No other result moves, and the
73	+/// number of messages does not change. For such a log, the snapshot order
74	+/// therefore no longer follows the event order one-to-one. The stored log
75	+/// does not change. A log with no `HandoffOccurred` event, and a log in the
76	+/// current layout, project in event order.
77	 pub fn project(events: &[SessionEvent]) -> ConversationSnapshot {
78	+    let (mut messages, sources) = project_events(events);
79	+    let moved = repair_legacy_transfer_results(events, &mut messages, &sources);
80	+    if moved > 0 {
81	+        tracing::debug!(
82	+            target: "paigasus::core::session",
83	+            moved,
84	+            "repaired legacy handoff transfer results"
85	+        );
86	+    }
87	+    ConversationSnapshot { messages }
88	+}
