90	+/// The index where the run of `ToolCalled` / `AssistantMessage` events
91	+/// directly before `handoff_at` starts.
92	+///
93	+/// The `ToolCalled` events in `start..handoff_at` are the transfer calls of
94	+/// the handoff response that the `HandoffOccurred` at `handoff_at` records.
95	+pub(crate) fn transfer_run_start(events: &[SessionEvent], handoff_at: usize) -> usize {
96	+    handoff_at
97	+        - events[..handoff_at]
98	+            .iter()
99	+            .rev()
100	+            .take_while(|e| {
101	+                matches!(
102	+                    e,
103	+                    SessionEvent::ToolCalled { .. } | SessionEvent::AssistantMessage { .. }
104	+                )
105	+            })
106	+            .count()
107	+}
