109	+/// The transfer calls of one handoff response.
110	+struct TransferResponse {
111	+    /// The incoming agent of the `HandoffOccurred` event.
112	+    to: String,
113	+    /// The event index of each transfer call, in call order.
114	+    calls: Vec<usize>,
115	+}
116	+
117	+/// Move the late result of each handoff transfer call to directly after the
118	+/// transfer calls of its response (sessions stored before SMA-810), and give
119	+/// a moved synthetic cancel result the transfer text. Returns the number of
120	+/// moved results.
121	+///
122	+/// `sources[m]` is the event index of `messages[m]`. The repair adds and
123	+/// removes no message. A result that is already directly after the transfer
124	+/// calls (the current layout) does not move, and no other result moves.
125	+fn repair_legacy_transfer_results(
126	+    events: &[SessionEvent],
127	+    messages: &mut Vec<Item>,
128	+    sources: &[usize],
129	+) -> usize {
130	+    // Step 1: the transfer calls of each handoff response.
131	+    let mut responses: Vec<TransferResponse> = Vec::new();
132	+    let mut is_transfer = vec![false; events.len()];
133	+    for (at, ev) in events.iter().enumerate() {
134	+        if let SessionEvent::HandoffOccurred { to, .. } = ev {
135	+            let calls: Vec<usize> = (transfer_run_start(events, at)..at)
136	+                .filter(|&i| matches!(events[i], SessionEvent::ToolCalled { .. }))
137	+                .collect();
138	+            for &c in &calls {
139	+                is_transfer[c] = true;
140	+            }
141	+            if !calls.is_empty() {
142	+                responses.push(TransferResponse {
143	+                    to: to.clone(),
144	+                    calls,
145	+                });
146	+            }
147	+        }
148	+    }
149	+    if responses.is_empty() {
150	+        return 0;
151	+    }
152	+
153	+    // Step 2: the result event of each transfer call. A result closes the most
154	+    // recent open non-transfer call with its id, else the earliest open
155	+    // transfer call with its id.
156	+    let mut result_of: Vec<Option<usize>> = vec![None; events.len()];
157	+    let mut open: Vec<(usize, &str)> = Vec::new();
158	+    for (at, ev) in events.iter().enumerate() {
159	+        match ev {
160	+            SessionEvent::ToolCalled { call_id, .. } => open.push((at, call_id)),
161	+            SessionEvent::ToolReturned { call_id, .. }
162	+            | SessionEvent::ToolDeferred { call_id, .. } => {
163	+                let pos = open
164	+                    .iter()
165	+                    .rposition(|&(c, id)| id == call_id && !is_transfer[c])
166	+                    .or_else(|| {
167	+                        open.iter()
168	+                            .position(|&(c, id)| id == call_id && is_transfer[c])
169	+                    });
170	+                if let Some(p) = pos {
171	+                    let (call, _) = open.remove(p);
172	+                    if is_transfer[call] && matches!(ev, SessionEvent::ToolReturned { .. }) {
173	+                        result_of[call] = Some(at);
174	+                    }
175	+                }
176	+            }
177	+            _ => {}
178	+        }
179	+    }
180	+
181	+    // Step 3 (done by the caller): the message index of each event.
182	+    let mut message_of: Vec<Option<usize>> = vec![None; events.len()];
183	+    for (m, &at) in sources.iter().enumerate() {
184	+        message_of[at] = Some(m);
185	+    }
186	+
187	+    // Step 4: plan the moves. `inserts` holds (anchor message, moved results);
188	+    // `rewrite[m]` holds the new text of a moved cancel result.
189	+    let mut moved = vec![false; messages.len()];
190	+    let mut rewrite: Vec<Option<String>> = vec![None; messages.len()];
191	+    let mut inserts: Vec<(usize, Vec<usize>)> = Vec::new();
192	+    for response in &responses {
193	+        let Some(last_call) = response.calls.iter().rev().find_map(|&c| message_of[c]) else {
194	+            continue;
195	+        };
196	+        // (message of the result, ordinal of its call in the response)
197	+        let results: Vec<(usize, usize)> = response
198	+            .calls
199	+            .iter()
200	+            .enumerate()
201	+            .filter(|&(_, &c)| message_of[c].is_some())
202	+            .filter_map(|(n, &c)| result_of[c].and_then(|r| message_of[r]).map(|m| (m, n)))
203	+            .collect();
204	+        let in_place = results
205	+            .iter()
206	+            .enumerate()
207	+            .take_while(|&(k, &(m, _))| m == last_call + 1 + k)
208	+            .count();
209	+        if in_place == results.len() {
210	+            continue;
211	+        }
212	+        let mut block = Vec::new();
213	+        for &(m, n) in &results[in_place..] {
214	+            moved[m] = true;
215	+            if is_cancel_text(&messages[m]) {
216	+                rewrite[m] = Some(if n == 0 {
217	+                    format!("transferred to {}", response.to)
218	+                } else {
219	+                    format!(
220	+                        "transfer not performed: this response already transferred to {}",
221	+                        response.to
222	+                    )
223	+                });
224	+            }
225	+            block.push(m);
226	+        }
227	+        inserts.push((last_call + in_place, block));
228	+    }
229	+    if inserts.is_empty() {
230	+        return 0;
231	+    }
232	+    inserts.sort_unstable_by_key(|&(anchor, _)| anchor);
233	+
234	+    // One rebuild pass.
235	+    let count = moved.iter().filter(|&&m| m).count();
236	+    let mut slots: Vec<Option<Item>> = std::mem::take(messages).into_iter().map(Some).collect();
237	+    for (m, text) in rewrite.into_iter().enumerate() {
238	+        if let (Some(text), Some(Item::ToolResult { content, .. })) = (text, slots[m].as_mut()) {
239	+            *content = vec![ContentPart::Text { text }];
240	+        }
241	+    }
242	+    let mut out = Vec::with_capacity(slots.len());
243	+    let mut next_insert = inserts.into_iter().peekable();
244	+    for m in 0..slots.len() {
245	+        if !moved[m] {
246	+            out.push(slots[m].take().expect("each message is taken once"));
247	+        }
248	+        while let Some((_, block)) = next_insert.next_if(|(anchor, _)| *anchor == m) {
249	+            for r in block {
250	+                out.push(slots[r].take().expect("each moved result is taken once"));
251	+            }
252	+        }
253	+    }
254	+    *messages = out;
255	+    count
256	+}
